(function(root,factory){if(typeof module==='object'&&module.exports)module.exports=factory();else root.DTProjectContext=factory();})(globalThis,function(){
'use strict';
const renderEpoch=new WeakMap();
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function diagram(service,flow){
 const entry=service.entries.find(e=>e.id===flow?.entry),exits=service.exits.filter(e=>flow?.exits.includes(e.id)).slice(0,20),height=Math.max(190,exits.length*65+30),y=height/2,style=flow?.basis==='assumption'?'assumed':'stated';
 const box=(x,y,label,kind)=>`<g><rect x="${x}" y="${y}" width="210" height="46" rx="5"/><text x="${x+12}" y="${y+18}">${esc(String(kind).slice(0,30))}</text><text x="${x+12}" y="${y+35}" class="pk-port-label">${esc(String(label).slice(0,30))}</text><title>${esc(label)}</title></g>`;
 return`<svg class="pk-graph" role="img" aria-label="Entry to exit map; independent arrows do not imply execution order" viewBox="0 0 830 ${height}"><defs><marker id="pk-arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto"><path d="M0 0 L10 5 L0 10Z"/></marker></defs>${entry?`<path class="${style}" marker-end="url(#pk-arrow)" d="M230 ${y} L310 ${y}"/>`:''}${exits.map((e,i)=>`<path class="${style}" marker-end="url(#pk-arrow)" d="M520 ${y} C560 ${y},560 ${53+i*65},600 ${53+i*65}"/>`).join('')}${entry?box(20,y-23,entry.label,entry.kind):''}${box(310,y-23,service.service,'Service & internal libraries')}${exits.map((e,i)=>box(600,30+i*65,e.label,e.kind)).join('')}</svg>`;
}
function tree(files){const root={dirs:new Map(),files:[]};for(const f of files){const parts=f.path.split('/');let at=root;for(const p of parts.slice(0,-1)){if(!at.dirs.has(p))at.dirs.set(p,{dirs:new Map(),files:[]});at=at.dirs.get(p);}at.files.push(f);}const render=n=>[...n.dirs].map(([name,value])=>`<details open><summary>${esc(name)}</summary>${render(value)}</details>`).join('')+n.files.map(f=>`<button data-pk-file="${esc(f.path)}"><strong>${esc(f.path.split('/').pop())}</strong><small>${esc(f.summary||f.mime)} · ${f.bytes.toLocaleString()} B</small></button>`).join('');return render(root);}
function render(root,data,options={}){
 const epoch=(renderEpoch.get(root)||0)+1;renderEpoch.set(root,epoch);
 const d=data.document||{},services=d.services||[];let service=services[0],flow=service?.flows[0],generation=0;
 root.innerHTML=`<div class="pk"><div class="pk-heading"><div><h2>${esc(d.title||'Project understanding')}</h2><p>${esc(d.summary)}</p></div><span class="pk-scope">Shared · ${data.canPublish?'admin publishes':'read only'}</span></div>${data.illustrative?'<p class="pk-notice">Illustrative project understanding, not measured service evidence.</p>':''}<p class="pk-meta">Revision <code>${esc(data.revision?.slice(0,16)||'unpublished')}</code> · ${esc(data.at||'')} · ${esc(data.author?.principalId||'')}<br>${esc(data.reason||'')}</p><p class="pk-notice">Published understanding is declared evidence. Check source revisions and assumptions. Static or Joern paths are not runtime traces; independent arrows do not imply execution order.</p><div class="pk-layout"><nav class="pk-nav" aria-label="Project services and evidence"><h3>Services</h3>${services.map(s=>`<button data-pk-service="${esc(s.service)}"><strong>${esc(s.service)}</strong><small>${s.entries.length} entries · ${s.exits.length} exits · ${s.flows.length} flows</small></button>`).join('')||'<p>No service contracts saved yet.</p>'}<h3>Evidence files</h3>${tree(data.files||[])||'<p>Save maps, screenshots, scripts, queries or findings with a publication.</p>'}</nav><section class="pk-main" aria-live="polite"><div data-pk-detail></div><div data-pk-file-preview></div></section></div><details><summary>Project explanation & related architecture</summary><pre class="pk-prose">${esc(d.body)}</pre>${(d.architecture||[]).map(a=>`<p>Architecture <code>${esc(a.id)}</code> @ <code>${esc(a.revision.slice(0,16))}</code></p>`).join('')}</details></div>`;
 const detail=root.querySelector('[data-pk-detail]'),preview=root.querySelector('[data-pk-file-preview]');
 const list=(label,items)=>items?.length?`<h4>${label}</h4><ul>${items.map(v=>'<li>'+esc(v)+'</li>').join('')}</ul>`:'';
 function show(){generation++;preview.replaceChildren();root.querySelectorAll('[data-pk-service]').forEach(b=>b.setAttribute('aria-current',String(b.dataset.pkService===service?.service)));if(!service){detail.innerHTML='<p class="pk-empty">Capture an architecture_service dossier, or publish a service contract with entry points, exits and evidence-backed flows.</p>';return;}
 detail.innerHTML=`<h3>${esc(service.service)}</h3><p>${esc(service.summary)}</p><p class="pk-meta">${esc(service.repo)} @ <code>${esc(service.revision||'source revision unknown')}</code></p><label>Entry-to-exit flow <select data-pk-flow aria-label="Entry-to-exit flow">${service.flows.map(f=>`<option value="${esc(f.id)}" ${f===flow?'selected':''}>${esc(f.summary||f.id)}</option>`).join('')}</select></label>${flow?`<div class="pk-graph-scroll">${diagram(service,flow)}</div><p class="pk-graph-hint">Scroll the diagram horizontally to inspect all boundaries.</p><p><strong>Declared basis: ${esc(flow.basis)}</strong> · ${service.entries.find(e=>e.id===flow.entry)?.label?esc(service.entries.find(e=>e.id===flow.entry).label):esc(flow.entry)} → ${flow.exits.length} exits</p>${list('Assumptions',flow.assumptions)}${list('Unresolved gaps',flow.gaps)}<h4>Evidence references</h4>${flow.evidence.length?'<ul>'+flow.evidence.map(e=>`<li><strong>${esc(e.source)}</strong> · <code>${esc(e.reference)}</code>${e.revision?' @ '+esc(e.revision):''}<p>${esc(e.note)}</p></li>`).join('')+'</ul>':'<p>This flow has no supporting evidence yet.</p>'}`:'<p>No entry-to-exit path is established yet. An inventory alone does not establish connections.</p>'}${list('Service assumptions',service.assumptions)}${list('Service gaps',service.gaps)}<details><summary>All discovered entry and exit boundaries</summary><h4>Entries</h4><ul>${service.entries.map(e=>'<li>'+esc(e.kind+' · '+e.label)+' <small>'+esc(e.source)+'</small></li>').join('')}</ul><h4>Exits</h4><ul>${service.exits.map(e=>'<li>'+esc(e.kind+' · '+e.label)+' <small>'+esc(e.source)+'</small></li>').join('')}</ul></details><p class="pk-test-guidance">Test outside-in: drive the entry through real service/library code, assert responses and exit effects, then verify SQL or transport with isolated dependencies. Mocked repository or producer calls establish no database or broker proof.</p>`;options.onService?.(service,flow);}
 async function open(file){const ticket=++generation;detail.hidden=true;preview.textContent='Loading retained file…';try{const result=await(options.readFile?options.readFile(file):Promise.resolve(data.file?.path===file?data:null));if(ticket!==generation||renderEpoch.get(root)!==epoch)return;const f=result?.file;if(!f){preview.textContent='Use project_context_get with this exact revision and path to read the file: '+file;return;}preview.innerHTML=`<h3>${esc(f.path)}</h3><p>${esc(f.summary)} · ${f.bytes.toLocaleString()} B</p>`;if(f.encoding==='base64'&&/^image\/(png|jpeg|webp)$/.test(f.mime)){const img=document.createElement('img');img.alt=f.summary||f.path;img.src='data:'+f.mime+';base64,'+f.content;preview.append(img);}else{const pre=document.createElement('pre');pre.className='pk-file-text';pre.textContent=f.encoding==='base64'?'Binary file. Download or read with encoding=base64. Stored artifacts never execute automatically.':f.content;preview.append(pre);}options.onFile?.(f);}catch(error){if(ticket===generation&&renderEpoch.get(root)===epoch)preview.textContent='Could not load file: '+error.message;}}
 root.onclick=event=>{const s=event.target.closest('[data-pk-service]'),f=event.target.closest('[data-pk-file]');if(s){service=services.find(v=>v.service===s.dataset.pkService);flow=service.flows[0];detail.hidden=false;show();}if(f)open(f.dataset.pkFile);};
 root.onchange=event=>{if(event.target.matches('[data-pk-flow]')){flow=service.flows.find(f=>f.id===event.target.value);show();}};show();if(data.file)open(data.file.path);
}
return{render,diagram,tree};
});
